private theorem cutoff_gaussian_bound {P t : ℝ} (hP : 0 < P) (ht : 0 < t) :
    (1 + |log (P/t)|) * exp (-(log (P/t))^2/4) ≤
      exp 9 * min 1 ((t/P)^2)

private theorem rational_decay (N : ℕ) (t : ℝ) :
    ‖(2+(t:ℂ)*I)*(1+(t:ℂ)*I)/clearingProduct (N+3) (2+(t:ℂ)*I)‖ ≤
      (∑ i : PoleIndex N, ‖residue N i*pole N i‖)*(1+t^2)⁻¹

